<?php
declare(strict_types=1);require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/task_workflow.php';require_login_any_role(['admin','employee']);$u=current_user();$uid=(int)$u['id'];$db=get_db();if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??null)){http_response_code(419);exit('Invalid request.');}task_notification_mutate($db,$uid,(string)($_POST['action']??''),isset($_POST['id'])?(int)$_POST['id']:null);header('Location: notifications.php?view='.urlencode((string)($_POST['view']??'all')),true,303);exit;}$view=($_GET['view']??'all')==='unread'?'unread':'all';$page=max(1,(int)($_GET['page']??1));$pageData=task_notification_page($db,$uid,$view,$page);$items=$pageData['notifications'];$unread=task_notification_unread_count($db,$uid);
function ne(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=ne(csrf_token())?>"><title>Notifications</title><?php require __DIR__.'/includes/pwa_head.php';?><style>body{margin:0;background:#f3f6fb;color:#172033;font:15px system-ui}.wrap{max-width:820px;margin:auto;padding:18px}.top,.item,.empty{background:#fff;border:1px solid #dbe3ef;border-radius:15px;padding:16px;margin-bottom:12px}.topline,.actions,.tabs{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.topline{justify-content:space-between}.tabs a,.button,button{padding:10px 13px;border-radius:9px;border:1px solid #b8c4d6;background:#fff;color:#174ea6;font:inherit;font-weight:700;text-decoration:none;min-height:42px}.tabs .active{background:#174ea6;color:#fff}.item.unread{border-left:5px solid #174ea6}.meta{color:#64748b;font-size:13px}.message{overflow-wrap:anywhere}.mutation-error{color:#b42318}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}html,body{max-width:100%;overflow-x:hidden}.actions form{margin:0}.actions button{cursor:pointer}.danger{color:#b42318}.warning{color:#8a4b00}.success{color:#067647}@media(max-width:480px){.wrap{padding:9px}.actions>*{flex:1}.actions button,.button{width:100%;text-align:center}}</style></head><body><main class="wrap"><section class="top"><div class="topline"><div><a href="<?=($u['role_name']==='admin'?'admin-dashboard.php':'employee-dashboard.php')?>">← Dashboard</a><h1>Notifications</h1><p><b data-visible-unread><?=$unread?></b> unread</p><p class="mutation-error" data-mutation-error role="alert" hidden></p><p class="sr-only" data-notification-live aria-live="polite"></p></div><?php require __DIR__.'/includes/notification_bell.php';?></div><div class="tabs"><a class="<?=$view==='unread'?'active':''?>" href="?view=unread">Unread</a><a class="<?=$view==='all'?'active':''?>" href="?view=all">All</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="read-all"><input type="hidden" name="view" value="<?=ne($view)?>"><button data-action="read-all">Mark all read</button></form></div></section><section aria-live="polite" id="notification-list"><?php if(!$items):?><div class="empty"><h2>You're all caught up</h2><p><?=$view==='unread'?'There are no unread notifications.':'There are no notifications to show.'?></p></div><?php endif;foreach($items as $n):?><article class="item <?=$n['status']==='unread'?'unread':''?>" data-id="<?=(int)$n['id']?>" data-status="<?=ne($n['status'])?>"><h2 class="<?=ne($n['tone'])?>"><?=ne($n['title'])?></h2><p class="message"><?=ne($n['message'])?></p><p class="meta"><?=ne($n['notification_type'])?> · Task #<?=(int)$n['source_task_id']?> · <time datetime="<?=ne($n['created_at'])?>"><?=ne($n['created_at'])?> IST</time></p><div class="actions"><a class="button" href="notification-open.php?id=<?=(int)$n['id']?>">Open exact task</a><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$n['id']?>"><input type="hidden" name="view" value="<?=ne($view)?>"><button name="action" value="<?=$n['status']==='unread'?'read':'unread'?>" data-action="<?=$n['status']==='unread'?'read':'unread'?>"><?=$n['status']==='unread'?'Mark read':'Mark unread'?></button></form><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$n['id']?>"><input type="hidden" name="view" value="<?=ne($view)?>"><button name="action" value="dismiss" class="danger" data-action="dismiss">Dismiss</button></form></div></article><?php endforeach?></section><nav class="tabs" aria-label="Pagination"><?php if($page>1):?><a href="?view=<?=$view?>&page=<?=$page-1?>">Previous</a><?php endif;if($pageData['has_more']):?><a href="?view=<?=$view?>&page=<?=$page+1?>">Next</a><?php endif?></nav></main><script>(function(){const list=document.getElementById('notification-list'),live=document.querySelector('[data-notification-live]'),error=document.querySelector('[data-mutation-error]'),unread=document.querySelector('[data-visible-unread]'),unreadView=<?=json_encode($view==='unread')?>;function empty(){if(!list.querySelector('[data-id]')&&!list.querySelector('.empty'))list.insertAdjacentHTML('beforeend',<?=json_encode("<div class=\"empty\"><h2>You are all caught up</h2><p>".($view==='unread'?'There are no unread notifications.':'There are no notifications to show.').'</p></div>')?>);}function paintCount(n){unread.textContent=String(n);if(window.TaskNotifications)window.TaskNotifications.paint(n);}async function act(b){if(b.dataset.busy)return;b.dataset.busy='1';b.disabled=true;error.hidden=true;const card=b.closest('[data-id]'),action=b.dataset.action;try{const r=await fetch('api/notifications.php?action='+action,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':document.querySelector('meta[name=csrf-token]').content,'Accept':'application/json'},credentials:'same-origin',cache:'no-store',body:JSON.stringify(card?{id:Number(card.dataset.id)}:{})}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error&&j.error.message||'Unable to update notification.');paintCount(Number(j.data.unread_count)||0);if(action==='dismiss'){const next=card.nextElementSibling||card.previousElementSibling;card.remove();empty();(next&&next.querySelector('button,a')||document.querySelector('[data-action="read-all"]')).focus();live.textContent='Notification dismissed.';}else if(action==='read-all'){document.querySelectorAll('[data-id]').forEach(c=>{c.classList.remove('unread');c.dataset.status='read';const x=c.querySelector('[data-action="read"]');if(x){x.dataset.action='unread';x.textContent='Mark unread';}if(unreadView)c.remove();});empty();b.focus();live.textContent='All notifications marked read.';}else{const reading=action==='read';card.classList.toggle('unread',!reading);card.dataset.status=reading?'read':'unread';b.dataset.action=reading?'unread':'read';b.textContent=reading?'Mark unread':'Mark read';if(reading&&unreadView){const next=card.nextElementSibling||card.previousElementSibling;card.remove();empty();(next&&next.querySelector('button,a')||document.querySelector('[data-action="read-all"]')).focus();}else b.focus();live.textContent=reading?'Notification marked read.':'Notification marked unread.';}document.dispatchEvent(new CustomEvent('task-notifications:refresh'));}catch(x){error.textContent=x.message||'Unable to update notification.';error.hidden=false;live.textContent='Notification update failed.';b.focus();}finally{delete b.dataset.busy;b.disabled=false;}}document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();act(b);});})();</script><?php require __DIR__.'/includes/mobile_app_nav.php';?></body></html>
